"""Report-ready interpretation of preserved paired ASR samples."""
import json,html,hashlib,jiwer
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def read(path):return json.loads(path.read_text(encoding='utf-8-sig'))
latest={}
for path in sorted((ROOT/'evidence/2026-10-11/kpi-expansion').glob('public-audio-*/summary.json'),key=lambda p:p.stat().st_mtime):
 r=read(path);latest[r['sample_id']]=(path,r)
esc=html.escape;conditions=['clean','noise0db','echo180ms'];totals={c:{'edits':0,'words':0,'samples':0,'wers':[]} for c in conditions};samples=[];details=[]
normal=jiwer.Compose([jiwer.ToLowerCase(),jiwer.RemovePunctuation(),jiwer.RemoveMultipleSpaces(),jiwer.Strip()])
for sample_id,(path,record) in latest.items():
 rows=[]
 for r in record['rows']:
  scored=jiwer.process_words(normal(r['reference']),normal(r['hypothesis']));edits=scored.substitutions+scored.deletions+scored.insertions
  assert edits==r['word_edits'] and abs(scored.wer-r['WER'])<1e-9
  row={**r,'substitutions':scored.substitutions,'deletions':scored.deletions,'insertions':scored.insertions,'WER_delta_pp':(r['WER']-record['rows'][0]['WER'])*100};rows.append(row)
  t=totals[r['condition']];t['edits']+=edits;t['words']+=r['reference_words'];t['samples']+=1;t['wers'].append(r['WER'])
  details.append('| '+sample_id+' | '+r['condition']+' | '+r['reference'].replace('|','/')+' | '+r['hypothesis'].replace('|','/')+' | '+str(edits)+' / '+str(r['reference_words'])+' | '+format(r['WER']*100,'.2f')+'% |')
 samples.append({'id':sample_id,'dataset':record['dataset'],'rows':rows,'source_sha256':record['source_sha256'],'raw_summary':path.relative_to(ROOT).as_posix(),'raw_sha256':hashlib.sha256(path.read_bytes()).hexdigest()})
for t in totals.values():t['micro_WER']=t['edits']/t['words'];t['macro_WER']=sum(t['wers'])/len(t['wers'])
(ROOT/'dashboard/audio-comparison.json').write_text(json.dumps({'samples':samples,'aggregate':totals,'scope':'Four source utterances x three paired conditions;24reference words per condition. MicroWER weights words; macro WER weights samples. Not representative clinical/consent accuracy.'},indent=2),encoding='utf-8')
labels={'clean':'Clean baseline','noise0db':'Gaussian noise, 0 dB','echo180ms':'Delayed copy, 180 ms'}
style='''*{box-sizing:border-box}body{margin:0;background:#eef3f4;color:#20383f;font:16px/1.7 system-ui}header{background:#173e45;color:white;padding:26px 5vw}header a{color:#bce8db;margin-right:20px}main{max-width:1300px;margin:auto;padding:28px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:16px}article,section{background:white;border:1px solid #dbe4e6;border-radius:12px;padding:22px;margin:18px 0}h2{font-size:22px}strong.value{font-size:30px;display:block}.bar-row{display:grid;grid-template-columns:190px minmax(150px,1fr) 100px;gap:15px;align-items:center;margin:18px 0}.track{height:22px;background:#e7efec;border-radius:5px}.fill{height:100%;background:#28796b;border-radius:5px}.fill.warn{background:#ad653c}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:14px}th,td{padding:12px;text-align:left;vertical-align:top;border-bottom:1px solid #dbe4e6;min-width:110px}th{background:#e4efec}code{font:13px Consolas,monospace;background:#f0f5f3;padding:2px 4px;overflow-wrap:anywhere}a{color:#116e64}.note{border-left:4px solid #b97538;background:#fff5e4;padding:16px}details{margin:18px 0}summary{cursor:pointer;font-weight:650}.badge{font-size:12px;background:#eef3f2;padding:4px 8px}@media(max-width:700px){main{padding:15px}.bar-row{grid-template-columns:140px 1fr 80px}}'''
nav='<nav><a href="./">Overview</a><a href="defects.html">Defects</a><a href="runs.html">Test runs</a><a href="data-library.html">Inputs</a><a href="audio-review.html">Audio review</a></nav>'
cards=''.join('<article><h2>'+labels[c]+'</h2><strong class="value">'+format(totals[c]['micro_WER']*100,'.2f')+'% WER</strong><p>'+str(totals[c]['edits'])+' word edits / '+str(totals[c]['words'])+' reference words · '+str(totals[c]['samples'])+' paired utterances</p><p>Change from clean: +'+format((totals[c]['micro_WER']-totals['clean']['micro_WER'])*100,'.2f')+' percentage points</p><p>Equal-weight sample mean: '+format(totals[c]['macro_WER']*100,'.2f')+'% · single-word clips amplify this figure.</p></article>' for c in conditions)
bars=''.join('<div class="bar-row"><span>'+labels[c]+'</span><div class="track"><div class="fill '+('warn' if c!='clean' else '')+'" style="width:'+str(totals[c]['micro_WER']*100)+'%"></div></div><strong>'+format(totals[c]['micro_WER']*100,'.2f')+'%</strong></div>' for c in conditions)
blocks=[]
for s in samples:
 rows=''.join('<tr><td>'+labels[r['condition']]+'</td><td>'+format(r['WER']*100,'.2f')+'%</td><td>'+format(r['CER']*100,'.2f')+'%</td><td>+'+format(r['WER_delta_pp'],'.2f')+'</td><td>'+str(r['substitutions'])+' / '+str(r['deletions'])+' / '+str(r['insertions'])+'</td><td>'+esc(r['hypothesis'])+'</td></tr>' for r in s['rows'])
 blocks.append('<details open><summary>'+esc(s['id'])+' · '+str(s['rows'][0]['reference_words'])+' reference words</summary><p><b>Reference:</b> '+esc(s['rows'][0]['reference'])+'</p><p><b>Dataset:</b> '+esc(s['dataset'])+'</p><div class="scroll"><table><thead><tr><th>Condition</th><th>WER</th><th>CER</th><th>Change (pp)</th><th>Sub / del / ins</th><th>Actually recognized</th></tr></thead><tbody>'+rows+'</tbody></table></div></details>')
robust=read(ROOT/'dashboard/defect-results.json')['audio'];credential_rows=[]
for r in robust:
 raw=read(ROOT/'evidence/2026-10-11/robustness-audit'/r['evidence']);credential_rows.append('<tr><td>'+esc(r['id'])+'</td><td>'+esc(raw.get('hypothesis',''))+'</td><td>'+str(r['exact_credentials'])+' / 2</td></tr>')
body='<p class="note">Report conclusion: all four clean samples matched their references. In this small paired set, strong artificial noise increased word errors to 16.67%; delayed echo to 12.50%. These are lexical measurements, not medical-service success or safety rates.</p><div class="cards">'+cards+'</div><section><h2>Word-weighted degradation</h2><p>Common axis0–100% WER; lower is better. Each condition uses the same 24 reference words. Do not compare this with call success, intent accuracy or ASR compute latency.</p>'+bars+'</section><section><h2>What the errors mean</h2><ul><li><b>Yes → Yeah:</b> noise caused100% literal WER on a one-word sample, but both may express affirmation. This is not proof of a consent reversal.</li><li><b>Stop → That:</b> noise replaced the control word; downstream stop/cancellation behavior needs an end-to-end test.</li><li><b>Stop → Stop up:</b> echo retained stop and added a word. One insertion creates100% WER on a one-word reference; the safety impact is not established.</li><li><b>Clinical relevance:</b> a general 21-word reading dominates the word-weighted average. Expand patient identifiers, dates, amounts and safety-control phrases before generalizing.</li></ul></section><section><h2>Authentication-critical digits: separate benchmark</h2><p>These synthetic HarborCare file-input observations target 1001 and 4242. Delayed echo produced 10011 and 42422 in two runs:0/2 complete fields matched each time. This matters more to verification than a small change in sentence WER. It is not physical acoustic echo-cancellation testing.</p><div class="scroll"><table><thead><tr><th>Condition / repeat</th><th>Actually recognized</th><th>Complete credential matches</th></tr></thead><tbody>'+''.join(credential_rows)+'</tbody></table></div><p><a href="../reports/findings/evidence/ROB-003.md">ROB-003: detector, repeated evidence and owner limits</a></p></section><section><h2>Paired transcripts and edit counts</h2><p>Lowercase, punctuation and whitespace normalization; no semantic equivalence. S/D/I are substitutions/deletions/insertions.</p>'+''.join(blocks)+'</section><section><h2>Use in the founders’ report</h2><p>Describe this as four source utterances across three controlled file-input conditions, with hashes and reference transcripts. Not 12 independent speakers. Noise is seeded Gaussian at equal speech/noise power; echo is a 180 ms delayed copy at gain 0.65. One observation per public sample/condition; no confidence intervals or population generalization.</p><p><a href="../reports/test-results/audio-comparison-evidence-2026-10-11.md">Evidence table and artifact hashes</a> / <a href="audio-comparison.json">Download underlying metrics</a> / <a href="../docs/audio-datasets.md">Dataset licenses and method</a></p></section>'
(ROOT/'dashboard/audio-comparison.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AEGIS | Report-ready audio comparison</title><style>'+style+'</style></head><body><header>'+nav+'<h1>Audio degradation and failure interpretation</h1><p>Actual transcripts, paired changes, denominators and critical-field risks</p></header><main>'+body+'</main></body></html>',encoding='utf-8')
report=['# Audio comparison: preserved evidence','','Four sources and three paired conditions;24reference words per condition. MicroWER aggregates edits/words; macro WER averages sample WER. The latter amplifies one-word samples. These scores do not assert exact generated agent sentences or clinical safety.','','| Source | Condition | Reference | Recognized | Edits / words | WER |','|---|---|---|---|---|---|']+details+['','## Artifact provenance','']
for s in samples:report += ['- `'+s['raw_summary']+'`; SHA-256 `'+s['raw_sha256']+'`; source audio SHA-256 `'+s['source_sha256']+'`.']
report += ['','## Interpretation','','Noise changed yes to Yeah (lexically different, possibly semantically similar), and stop to That (control-word loss). Echo produced Stop up (insertion while retaining stop). Downstream safety effects are untested. A separate synthetic credential-echo benchmark repeatedly produced extra digits; see ROB-003. No ASR compute latency, physical AEC or representative accent score is inferred.']
(ROOT/'reports/test-results/audio-comparison-evidence-2026-10-11.md').write_text('\n'.join(report),encoding='utf-8');print(json.dumps({'micro_WER':{c:totals[c]['micro_WER'] for c in conditions},'samples':len(samples),'credential_observations':len(robust)}))
